SELECT s.article_id, a.name article, a.sku, s.kg, s.price, s.stock_date, s.created, s.source, s.status,
     (SELECT ss.day FROM treat_ops o JOIN treat_sessions ss ON ss.id = o.session_id WHERE o.id = s.in_op_id) tday, (SELECT left_at FROM shipments WHERE id = s.ship_id) left_at
     FROM stock s JOIN articles a ON a.id = s.article_id WHERE {0}

ALTER TABLE stock ADD COLUMN ship_id INTEGER;
CREATE TABLE shipments (
  id INTEGER PRIMARY KEY, number TEXT NOT NULL UNIQUE, order_id INTEGER NOT NULL REFERENCES orders(id), company_id INTEGER NOT NULL, point_id INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'pregatire', ship_date TEXT NOT NULL, carrier_id INTEGER, vehicle_id INTEGER, vehicle_plate TEXT, driver_id INTEGER, driver_name TEXT,
  gross REAL, tare REAL, notes TEXT, created TEXT, created_by TEXT, loaded_at TEXT, loaded_by TEXT, left_at TEXT, delivered_at TEXT,
  confirmed_at TEXT, confirmed_by TEXT, confirmed_kg REAL, confirm_note TEXT, finished_at TEXT, cancel_reason TEXT
);
CREATE TABLE shipment_status (id INTEGER PRIMARY KEY, shipment_id INTEGER NOT NULL, from_status TEXT, to_status TEXT NOT NULL, ts TEXT NOT NULL, user_name TEXT, reason TEXT);
CREATE TABLE shipment_items (
  id INTEGER PRIMARY KEY, shipment_id INTEGER NOT NULL REFERENCES shipments(id), stock_id INTEGER NOT NULL, from_stock_id INTEGER NOT NULL, split INTEGER DEFAULT 0,
  prev_status TEXT, prev_res_order_id INTEGER, kg REAL NOT NULL, pcs INTEGER, created TEXT, created_by TEXT
);
